          steamGrad.addColorStop(0.45, `rgba(240, 215, 190, ${p.opacity * 0.6})`);
          steamGrad.addColorStop(0.8, `rgba(200, 180, 160, ${p.opacity * 0.2})`);
          steamGrad.addColorStop(1, 'rgba(100, 90, 80, 0)');

