            mote.y += mote.vy;
            mote.pulse += mote.pulseSpeed;

            if (mote.y < 0) {
              mote.y = height + 10;
              mote.x = Math.random() * width;
            }
            if (mote.x < 0) mote.x = width;
            if (mote.x > width) mote.x = 0;
          }

          const currentOpacity = mote.opacity * (0.6 + Math.sin(mote.pulse) * 0.4);

          ctx.beginPath();
          ctx.arc(mote.x, mote.y, mote.size, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(255, 225, 180, ${currentOpacity})`;
          ctx.fill();
        }
        ctx.restore();
      }

