          mouse.lightY += ((mouse.y - centerY) - mouse.lightY) * 0.08;
        } else {
          mouse.tiltX = 0;
          mouse.tiltY = 0;
          mouse.lightX = 0;
          mouse.lightY = 0;
        }

        // Reset transform and render frame
        ctx.save();
        ctx.scale(dpr, dpr);

        // 1. Atmospheric Dark Timber Countertop & Ambient Lantern Glow
        renderAtmosphericBackground(time);

        // 2. Tenmoku Ceramic Stoneware Bowl & Rim Lighting
        renderCeramicBowl(time);

        // 3. Silky Creamy Vegan Broth, Ripples & Floating Oil Beads
        renderBroth(time);

        // 4. Handcrafted Vegan Ramen Toppings (Tofu, Shiitake, Egg, Bok Choy, Nori, etc.)
        renderToppings(time);

        // 5. Volumetric Rising Steam & Heat Dispersion
        renderSteam(time);

        // 6. Ambient Floating Warm Light Dust Motes
        renderDustMotes(time);

        ctx.restore();

        requestAnimationFrame(animate);
      }

      requestAnimationFrame(animate);

    })();
